#!/bin/sh
# macOS CI (arm64 and x86_64). POSIX sh: macOS runners ship bash 3.2.
#
#   sh .github/ci/macos.sh seed   wasm seed through cmake/ (no LLVM):
#       arm64  (Native backend): seed -> Stage1 -> Stage2 -> Stage3 == Stage4,
#              Stage2 rebuilds the committed seed byte for byte, test suite
#       x86_64 (no Native backend): seed -> Stage1, Stage1 rebuilds the seed
#   sh .github/ci/macos.sh llvm   C Stage0 against the pinned LLVM SDK,
#       LLVM-enabled Stage2, convergence, test suite:
#       arm64:  ./build.sh verify --enable-llvm (Native, LLVM, Native == LLVM)
#       x86_64: Stage2 generated by LLVM, LLVM Stage3 == Stage4
#
# LLVM, pinned by version and file name (as Zig and Rust pin theirs), cached
# by the workflow in $LLVM_SDK:
#   arm64:  the upstream release archive; it ships only component archives,
#           so libLLVM.dylib is linked here from them.
#   x86_64: no upstream archive exists for 22.1.8, so the pinned source is
#           built (hours, once; then cached).
set -eu

job=${1:?usage: macos.sh seed|llvm}
version=22.1.8
sdk=${LLVM_SDK:-$HOME/llvm-sdk-$version}

case "$(uname -m)" in
arm64) native=yes ;;
x86_64) native=no ;;
*)
    echo "macos.sh: unsupported machine $(uname -m)" >&2
    exit 2
    ;;
esac

fetch() { # url file
    curl -fL --retry 3 -o "$2" "$1"
}

provision_llvm() {
    if [ -f "$sdk/lib/libLLVM.dylib" ] && [ -x "$sdk/bin/llvm-config" ]; then
        echo "LLVM SDK restored from cache: $sdk"
        return
    fi
    work=${RUNNER_TEMP:-/tmp}/llvm-work
    rm -rf "$work" "$sdk"
    mkdir -p "$work" "$sdk/bin" "$sdk/lib"
    base=https://github.com/llvm/llvm-project/releases/download/llvmorg-$version
    if [ "$native" = yes ]; then
        asset=LLVM-$version-macOS-ARM64
        fetch "$base/$asset.tar.xz" "$work/$asset.tar.xz"
        # Only what the build uses: headers, component archives, tools.
        tar -xf "$work/$asset.tar.xz" -C "$work" \
            "$asset/include" "$asset/lib/libLLVM*.a" "$asset/lib/libPolly*.a" \
            "$asset/bin/llvm-config" "$asset/bin/llvm-nm" "$asset/bin/llvm-readobj"
        rm -f "$work/$asset.tar.xz"
        root=$work/$asset
        archives=$("$root/bin/llvm-config" --link-static --libfiles all)
        system_libs=$("$root/bin/llvm-config" --link-static --system-libs)
        # shellcheck disable=SC2086 # one word per archive / library
        clang++ -dynamiclib -o "$root/lib/libLLVM.dylib" -install_name @rpath/libLLVM.dylib \
            -Wl,-all_load $archives $system_libs
        cp "$root/bin/llvm-config" "$root/bin/llvm-nm" "$root/bin/llvm-readobj" "$sdk/bin/"
        cp -R "$root/include" "$sdk/include"
        cp "$root/lib/libLLVM.dylib" "$sdk/lib/"
        ln -sf libLLVM.dylib "$sdk/lib/libLLVM-22.dylib"
    else
        fetch "$base/llvm-project-$version.src.tar.xz" "$work/src.tar.xz"
        tar -xf "$work/src.tar.xz" -C "$work"
        cmake -S "$work/llvm-project-$version.src/llvm" -B "$work/build" \
            -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX="$sdk" \
            -DLLVM_TARGETS_TO_BUILD=all \
            -DLLVM_BUILD_LLVM_DYLIB=ON -DLLVM_LINK_LLVM_DYLIB=ON \
            -DLLVM_ENABLE_LIBXML2=OFF -DLLVM_ENABLE_ZSTD=OFF \
            -DLLVM_INCLUDE_TESTS=OFF -DLLVM_INCLUDE_EXAMPLES=OFF \
            -DLLVM_INCLUDE_BENCHMARKS=OFF -DLLVM_INCLUDE_DOCS=OFF \
            -DLLVM_ENABLE_BINDINGS=OFF -DLLVM_BUILD_UTILS=OFF
        cmake --build "$work/build" --parallel "$(sysctl -n hw.ncpu)"
        cmake --install "$work/build"
    fi
    rm -rf "$work"
    echo "LLVM SDK built: $sdk"
}

case "$job" in
seed)
    if [ "$native" = yes ]; then
        ./build.sh verify --bootstrap=wasm
        cmake --build build/bootstrap/cmake-wasm --target sultanc-check-seed
        SC=build/sultanc bash tools/tests/ci_run.sh
    else
        ./build.sh bootstrap --bootstrap=wasm
        build/bootstrap/sultanc-stage1 version
        cmake --build build/bootstrap/cmake-wasm --target sultanc-check-seed
    fi
    ;;
llvm)
    provision_llvm
    export LLVM_CONFIG="$sdk/bin/llvm-config"
    export DYLD_LIBRARY_PATH="$sdk/lib${DYLD_LIBRARY_PATH:+:$DYLD_LIBRARY_PATH}"
    echo "LLVM $("$LLVM_CONFIG" --version) from $sdk"
    if [ "$native" = yes ]; then
        ./build.sh verify --enable-llvm
    else
        ./build.sh --enable-llvm --backend=llvm
        d=build/ci-llvm
        rm -rf "$d"
        mkdir -p "$d"
        build/sultanc compiler/main.sn --backend=llvm -o "$d/stage3" "$sdk/lib/libLLVM.dylib"
        "$d/stage3" compiler/main.sn --backend=llvm -o "$d/stage4" "$sdk/lib/libLLVM.dylib"
        cmp "$d/stage3" "$d/stage4"
        echo "LLVM convergence: Stage3 == Stage4"
    fi
    SC=build/sultanc bash tools/tests/ci_run.sh
    ;;
*)
    echo "usage: macos.sh seed|llvm" >&2
    exit 2
    ;;
esac
